USE studybuddy;
CREATE TABLE IF NOT EXISTS study_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, subject_code VARCHAR(60) NOT NULL, game_type VARCHAR(40) NOT NULL, accuracy DECIMAL(5,2) NOT NULL DEFAULT 0, seconds INT UNSIGNED NOT NULL DEFAULT 0, points INT UNSIGNED NOT NULL DEFAULT 0, completed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS question_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, session_id BIGINT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, subject_code VARCHAR(60) NOT NULL, topic VARCHAR(160) NOT NULL, correct BOOLEAN NOT NULL, response_seconds INT UNSIGNED NOT NULL DEFAULT 0);
